def format_long_text(text: str, color: str='', columns: int=
    get_terminal_size().columns, start_line_decorator: str=' ',
    end_line_decorator: str=' ', max_lines: Optional[int]=None, styling:
    Optional[Dict[str, Any]]=None, indent: str='', sub_indent: str='') ->str:
    if color:
        text = click.style(text, fg=color)

    wrapper = textwrap.TextWrapper(
        width=max(1, columns - len(click.unstyle(start_line_decorator)) - len(click.unstyle(end_line_decorator))),
        initial_indent=indent,
        subsequent_indent=sub_indent,
        break_long_words=False,
        break_on_hyphens=False
    )

    wrapped_lines = wrapper.wrap(click.unstyle(text) if color else text)

    if color:
        if wrapped_lines:
            wrapped_lines[0] = click.style(wrapped_lines[0].lstrip(indent), fg=color)
            if indent:
                wrapped_lines[0] = indent + wrapped_lines[0]
            for i in range(1, len(wrapped_lines)):
                line_content = wrapped_lines[i].lstrip(sub_indent)
                wrapped_lines[i] = sub_indent + click.style(line_content, fg=color)

    if max_lines is not None:
        wrapped_lines = wrapped_lines[:max_lines]

    if not wrapped_lines:
        wrapped_lines = ['']

    result_lines = []
    for line in wrapped_lines:
        result_lines.append(f"{start_line_decorator}{line}{end_line_decorator}")

    return '\n'.join(result_lines)
